import json
import socket

def test():
    data = {"hello world!"}
    with open('data.json', 'w') as f:
        json.dump(data, f)

while True:
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        try:
            s.connect(("target_server", 443))
            s.sendall("POST / HTTP/1.1\r\nHost: target_server\r\nContent-Type: application/json\r\nContent-Length: " + str(len(json.dumps(data))) + "\r\n\r\n" + json.dumps(data).encode("utf-8"))
        except:
            pass
